import {
  Fieldset as FieldsetPrimitive,
  useFieldset,
  useFieldsetContext,
} from '@ark-ui/solid/fieldset';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import styles from './Fieldset.module.css';

function Fieldset(props: ComponentProps<typeof FieldsetPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FieldsetPrimitive.Root
      {...others}
      data-slot="fieldset-root"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldsetRootProvider(props: ComponentProps<typeof FieldsetPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FieldsetPrimitive.RootProvider
      {...others}
      data-slot="fieldset-root-provider"
      class={clsx(styles.root, local.class)}
    />
  );
}

function FieldsetLegend(props: ComponentProps<typeof FieldsetPrimitive.Legend>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FieldsetPrimitive.Legend
      {...others}
      data-slot="fieldset-legend"
      class={clsx(styles.legend, local.class)}
    />
  );
}

function FieldsetHelperText(props: ComponentProps<typeof FieldsetPrimitive.HelperText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FieldsetPrimitive.HelperText
      {...others}
      data-slot="fieldset-helper-text"
      class={clsx(styles.helperText, local.class)}
    />
  );
}

function FieldsetErrorText(props: ComponentProps<typeof FieldsetPrimitive.ErrorText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <FieldsetPrimitive.ErrorText
      {...others}
      data-slot="fieldset-error-text"
      class={clsx(styles.errorText, local.class)}
    />
  );
}

const FieldsetContext = FieldsetPrimitive.Context;

export {
  Fieldset,
  FieldsetContext,
  FieldsetErrorText,
  FieldsetHelperText,
  FieldsetLegend,
  FieldsetRootProvider,
  useFieldset,
  useFieldsetContext,
};

export type {
  FieldsetContextProps,
  FieldsetErrorTextProps,
  FieldsetHelperTextProps,
  FieldsetLegendProps,
  FieldsetRootProps,
  FieldsetRootProviderProps,
  UseFieldsetContext,
  UseFieldsetProps,
  UseFieldsetReturn,
} from '@ark-ui/solid/fieldset';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-spacing-4);
    width: 100%;
    min-inline-size: 0;
    margin: 0;
    padding: 0;
    border: 0;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .legend {
    max-inline-size: 100%;
    overflow-wrap: anywhere;
    margin: 0;
    padding: 0 0 var(--moduix-spacing-3);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-lg);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-lg);
  }

  .helperText,
  .errorText {
    margin: 0;
    overflow-wrap: anywhere;
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
  }

  .helperText {
    color: var(--moduix-color-muted-foreground);
  }

  .errorText {
    color: var(--moduix-color-destructive);
    font-weight: var(--moduix-weight-medium);
  }
}
